## 3. Result-Generation Logic (form data → recommendation)

The recommendation is computed by the inline `evaluate()` function in the compass page (no separate logic lib for this module). The generic PDF helper used to render/export results follows below.

Source: `client/src/pages/EmbryoCryoCompass.tsx`

```typescript
type EmbryoCryoIndication = "oncofertility" | "ivf_excess" | "pgt" | "defer_transfer" | "donor";

interface EmbryoCryoInputs {
  indication: EmbryoCryoIndication;
  gonadotoxicTherapy: boolean;
  ovarianHyperstimulationRisk: boolean;
  endometrialIssue: boolean;
  pgtPlanned: boolean;
  excessEmbryos: boolean;
  embryoCount: number;
  singleEmbryo: boolean;
  storageYears: number;
}

const defaultInputs: EmbryoCryoInputs = {
  indication: "ivf_excess", gonadotoxicTherapy: false,
  ovarianHyperstimulationRisk: false, endometrialIssue: false,
  pgtPlanned: false, excessEmbryos: false, embryoCount: 0,
  singleEmbryo: false, storageYears: 0,
};

function evaluate(inputs: EmbryoCryoInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Practice Committees of ASRM and SART. Criteria for number of embryos to transfer: a committee opinion. Fertil Steril. 2021;116(3):651-654.",
    "Cobo A, et al. Elective and Onco-fertility Preservation: Factors Related to IVF Outcomes. Hum Reprod. 2018;33(12):2222-2231.",
    "ASRM Practice Committee. Cryopreservation of embryos and oocytes. Fertil Steril. 2013;99(1):37-43.",
    "Oktay K, et al. Fertility Preservation in Patients With Cancer: ASCO Clinical Practice Guideline Update. J Clin Oncol. 2018;36(19):1994-2001.",
  ];

  let recommendation = "indicated";
  let procedure = "";
  let cor = "I";
  let loe = "A";

  if (inputs.indication === "oncofertility" && inputs.gonadotoxicTherapy) {
    procedure = "Embryo cryopreservation — oncofertility (medical necessity)";
    cor = "I"; loe = "A";
    rationale.push("Gonadotoxic therapy planned: ASCO 2018 guideline recommends embryo cryopreservation as standard of care for fertility preservation before gonadotoxic treatment.");
    rationale.push("Embryo cryopreservation has the highest success rates of all fertility preservation methods.");
  } else if (inputs.indication === "ivf_excess") {
    procedure = "Embryo cryopreservation — excess embryos from IVF cycle";
    cor = "I"; loe = "A";
    rationale.push("Excess embryos: cryopreservation of supernumerary embryos is standard practice in IVF. Frozen embryo transfer (FET) cycles have equivalent or superior outcomes to fresh transfers.");
    if (inputs.ovarianHyperstimulationRisk) {
      rationale.push("OHSS risk: freeze-all strategy is indicated to prevent ovarian hyperstimulation syndrome. All embryos should be cryopreserved for deferred transfer.");
      warnings.push("Freeze-all strategy recommended: fresh transfer contraindicated with OHSS risk. Deferred FET after ovarian recovery.");
    }
    if (inputs.endometrialIssue) {
      rationale.push("Endometrial issue identified: deferred FET allows endometrial optimization before transfer.");
    }
  } else if (inputs.indication === "pgt") {
    procedure = "Embryo cryopreservation — for PGT biopsy and results";
    cor = "I"; loe = "A";
    rationale.push("PGT planned: embryos must be cryopreserved during biopsy and while awaiting genetic results. This is a required step in the PGT process.");
  } else if (inputs.indication === "defer_transfer") {
    procedure = "Elective embryo cryopreservation — deferred transfer";
    cor = "IIa"; loe = "B";
    rationale.push("Elective freeze: patient preference to defer embryo transfer. Frozen embryo transfer outcomes are comparable to fresh transfer.");
  } else {
    procedure = "Embryo cryopreservation — donor embryo banking";
    cor = "I"; loe = "B";
    rationale.push("Donor embryo banking: cryopreservation is required for quarantine period and recipient matching.");
  }

  if (inputs.storageYears > 10) {
    warnings.push(`Long-term storage (${inputs.storageYears} years): discuss embryo disposition options with patient. Annual storage fees are typically not covered by insurance.`);
  }

  warnings.push("Annual embryo storage fees (CPT 89344) are almost universally excluded from insurance coverage. Patients should budget for self-pay storage costs ($500–$1,000/year).");

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}

// PDF export of the result (assembles plain-text summary, calls exportAssessmentPDF)
const handleExportPDF = () => {
  if (!result) return;
  const content = `EMBRYO CRYOPRESERVATION — CLINICAL DECISION SUPPORT\n\nIndication: ${inputs.indication}\nGonadotoxic Therapy: ${inputs.gonadotoxicTherapy ? "Yes" : "No"}\nOHSS Risk: ${inputs.ovarianHyperstimulationRisk ? "Yes" : "No"}\nPGT Planned: ${inputs.pgtPlanned ? "Yes" : "No"}\nEmbryo Count: ${inputs.embryoCount}\n\nASSESSMENT\nProcedure: ${result.procedure}\nCOR: ${result.cor} | LOE: ${result.loe}\n\nRATIONALE\n${result.rationale.map((r, i) => `${i + 1}. ${r}`).join("\n")}\n\nWARNINGS\n${result.warnings.map((w, i) => `${i + 1}. ${w}`).join("\n")}\n\nREFERENCES\n${result.references.map((r, i) => `${i + 1}. ${r}`).join("\n")}`;
  exportAssessmentPDF({ title: "Embryo Cryopreservation Clinical Compass", filename: "embryo-cryo-assessment.pdf", content });
};
